/**
 * 本地图片路径工具
 * 所有本地图片都存放在 public/images/ 目录下
 * 在子路径部署（妙搭平台 / GitHub Pages）下自动拼接 basename
 *
 * 修复：GitHub Pages 环境下不使用 resolveAppUrl，因为它会返回妙搭平台格式的路径
 *
 * Storage 优化：同步后 base64 替换为 GitHub 路径（/images/custom/...），
 * 在妙搭平台管理后台，这些图片需要从 GitHub raw URL 加载；
 * 在 GitHub Pages 前台，直接用 basename 拼接即可。
 */

import { resolveAssetUrl, isMiaodaPlatform } from './basename';

const GITHUB_CONFIG_KEY = '__app_ledlight_github_config_v1';

interface GithubRawConfig {
  owner: string;
  repo: string;
  branch: string;
  enabled: boolean;
}

function getGithubRawConfig(): GithubRawConfig | null {
  try {
    const raw = localStorage.getItem(GITHUB_CONFIG_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<GithubRawConfig>;
    if (parsed.enabled && parsed.owner && parsed.repo && parsed.branch) {
      return {
        owner: parsed.owner,
        repo: parsed.repo,
        branch: parsed.branch || 'main',
        enabled: true,
      };
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * 获取本地图片的完整 URL
 * @param name 图片文件名，如 'hero-slide-1.jpg'
 * @returns 完整 URL（含 basename 前缀）
 *
 * 支持的输入格式：
 * - 纯文件名：'hero.jpg' → /images/hero.jpg（加 basename）
 * - 绝对路径：'/images/hero.jpg' → 加 basename
 * - 相对路径：'./images/hero.jpg' → 规范化后加 basename
 * - 子路径前缀：'/repo/images/hero.jpg' → 已含 basename，直接返回（幂等）
 * - 妙搭 storage 路径（/spark/ 开头）→ 直接返回，不加 basename
 * - base64 / 远程 URL → 直接返回
   */
export function imgPath(name: string): string {
  if (!name) return name;
  // data: URI (base64 等) 直接返回，不拼接路径
  if (name.startsWith('data:')) return name;
  // 绝对 URL (http/https/ftp 等) 直接返回
  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(name)) return name;
  // blob: URL 直接返回
  if (name.startsWith('blob:')) return name;
  // 妙搭平台 storage 静态资源路径（/spark/app/.../static/...），直接返回不加 basename
  if (name.startsWith('/spark/')) return name;

  // 规范化路径：统一成以 / 开头的绝对路径形式
  let path: string;
  if (name.startsWith('/')) {
    path = name;
  } else if (name.startsWith('./')) {
    // 相对路径 ./images/... → 去掉 ./ 变成 images/...，再加前缀 /
    path = '/' + name.slice(2);
  } else if (name.startsWith('images/')) {
    // 相对路径 images/... → 加前缀 /
    path = '/' + name;
  } else {
    // 纯文件名，加上 /images/ 前缀
    path = `/images/${name}`;
  }

  // Storage 优化：GitHub 同步后的自定义图片路径
  // 妙搭平台管理后台 → 用 GitHub raw URL 加载（图片在 GitHub 不在妙搭）
  // GitHub Pages / 本地开发 → 用 basename 拼接（图片和站点同仓库）
  if (path.startsWith('/images/custom/')) {
    const ghConfig = getGithubRawConfig();
    if (isMiaodaPlatform() && ghConfig) {
      // 管理后台：从 GitHub raw 加载
      const rawPath = path.replace(/^\/images\/custom\//, 'images/custom/');
      return `https://raw.githubusercontent.com/${ghConfig.owner}/${ghConfig.repo}/${ghConfig.branch}/${rawPath}`;
    }
    // GitHub Pages 或本地开发：直接用相对路径 + basename
    return resolveAssetUrl(path);
  }

  return resolveAssetUrl(path);
}

/**
 * 修复 HTML 内容中所有 <img> 标签的 src 路径
 * 将本地路径（/images/、/images/custom/、/spark/ 等）转换为带 basename 的正确路径
 * 用于 dangerouslySetInnerHTML 渲染的富文本内容（新闻文章、产品描述等）
 *
 * 🔴 修复：之前只处理 /images/ 开头的路径，漏掉了 /images/custom/（GitHub 同步后）和 /spark/（妙搭 storage）。
 * 实际上 imgPath() 内部已经能处理所有这些格式，只需放宽正则匹配条件。
 */
export function fixHtmlImagePaths(html: string): string {
  if (!html) return html;
  // 匹配 <img ... src="..." ...> 和 <img ... src='...' ...>
  return html.replace(
    /(<img[^>]+src=)(["'])([^"']+)(\2[^>]*>)/gi,
    (match, prefix: string, quote: string, src: string, suffix: string) => {
      // 跳过已处理的外部 URL（http/https）、base64、blob
      if (
        src.startsWith('data:') ||
        src.startsWith('blob:') ||
        /^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(src)
      ) {
        return match;
      }
      // 所有本地路径（/images/、/images/custom/、/spark/、./images/、images/ 等）都走 imgPath
      return `${prefix}${quote}${imgPath(src)}${suffix}`;
    },
  );
}
